// Illustrated banners generated by scripts/generate-page-images.mjs (1600px and 800px WebP in /public/images).
export type Art = { src: string; srcSet: string };

const make = (base: string): Art => ({ src: `${base}.webp`, srcSet: `${base}-sm.webp 800w, ${base}.webp 1600w` });

export const serviceArt = (slug: string): Art => make(`/images/services/${slug}`);
export const aboutArt: Art = make("/images/about");

// Blog categories and demo categories borrow the illustration of the closest product.
const blogMap: Record<string, string> = {
  Websites: "website-development",
  "Business software": "crm-software",
  Support: "bug-fixing-maintenance",
  AI: "ai-solutions",
  Guides: "technology-consulting",
  Engineering: "web-app-development",
  Strategy: "technology-consulting",
};
const demoMap: Record<string, string> = {
  CRM: "crm-software",
  POS: "pos-hrms-software",
  HRMS: "pos-hrms-software",
  Hospitality: "erp-software",
  Education: "web-app-development",
  Healthcare: "security-audit",
  Operations: "erp-software",
};

export const blogArt = (category: string): Art => serviceArt(blogMap[category] ?? "technology-consulting");
export const demoArt = (category: string): Art => serviceArt(demoMap[category] ?? "web-app-development");
